{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Test a modest increase from width 48 to 52 across all four category models. Existing dimension-dependent layers, checkpoint metadata and the embedded predictor propagate this width consistently while preserving tied embeddings, causal topology, scoring, loss and optimizer.",
      "edits": [
        {
          "find": "HIDDEN_UNITS  = int(os.environ.get(\"NEXTITNET_HIDDEN\", \"48\"))",
          "replace": "HIDDEN_UNITS  = int(os.environ.get(\"NEXTITNET_HIDDEN\", \"52\"))"
        }
      ]
    }
  ],
  "change_summary": "Increase tied item-embedding and matching hidden width to 52, retaining one NextItNet checkpoint per category and metadata-driven predictor compatibility."
}
